using System;
using System.Text;
using UnityEditor;
using UnityEngine;

public class FishCompileProbe
{
    public static void Run()
    {
        string[] names = new string[]
        {
            "Module.Fish.Service.FishSpawnService, Assembly-CSharp",
            "Module.Fish.View.HookViewController, Assembly-CSharp",
            "Module.Fish.View.FishingLineView, Assembly-CSharp",
            "Module.Fish.View.FishingCameraRig, Assembly-CSharp",
            "Module.Fish.FishingController, Assembly-CSharp",
            "Module.Fish.FishingScene, Assembly-CSharp"
        };

        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < names.Length; i++)
        {
            Type type = Type.GetType(names[i]);
            sb.AppendLine((type == null ? "MISSING " : "OK      ") + names[i]);
        }

        Debug.Log("[FishCompileProbe]\n" + sb);
    }
}
